-- The per-client knowledge base (docs/plan.md §1.21): FAQs and policies with their versions, and the
-- searchable passages of entries and documents (Postgres full-text search). New tables only, so the
-- previous Worker keeps working. Generated by drizzle-kit; the grants, row-level security and the
-- immutability trigger at the end are hand-written, as in 0004 and 0005.
CREATE TABLE "knowledge_chunk" (
	"id" uuid PRIMARY KEY DEFAULT uuid_generate_v7() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"source_type" text NOT NULL,
	"entry_id" uuid,
	"entry_version_id" uuid,
	"document_id" uuid,
	"extraction_id" uuid,
	"chunk_no" integer NOT NULL,
	"title" text NOT NULL,
	"body" text NOT NULL,
	"config" text DEFAULT 'english' NOT NULL,
	"tsv" "tsvector" NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "knowledge_chunk_source_check" CHECK ("knowledge_chunk"."source_type" in ('entry', 'document')),
	CONSTRAINT "knowledge_chunk_source_ids_check" CHECK (("knowledge_chunk"."source_type" = 'entry' and "knowledge_chunk"."entry_id" is not null and "knowledge_chunk"."entry_version_id" is not null and "knowledge_chunk"."document_id" is null) or ("knowledge_chunk"."source_type" = 'document' and "knowledge_chunk"."document_id" is not null and "knowledge_chunk"."entry_id" is null))
);
