CREATE TABLE "knowledge_entry" (
	"id" uuid PRIMARY KEY DEFAULT uuid_generate_v7() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"kind" text NOT NULL,
	"status" text DEFAULT 'active' NOT NULL,
	"version" integer DEFAULT 1 NOT NULL,
	"created_by" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "knowledge_entry_id_tenant_key" UNIQUE("id","tenant_id"),
	CONSTRAINT "knowledge_entry_kind_check" CHECK ("knowledge_entry"."kind" in ('faq', 'policy')),
	CONSTRAINT "knowledge_entry_status_check" CHECK ("knowledge_entry"."status" in ('active', 'archived'))
);
--> statement-breakpoint
