	CONSTRAINT "knowledge_entry_version_role_check" CHECK ("knowledge_entry_version"."author_role" in ('operator', 'client_admin')),
	CONSTRAINT "knowledge_entry_version_number_check" CHECK ("knowledge_entry_version"."version" >= 1)
);
